-- Read-only audit for Supabase E2E. Do not run against production.
select ns.nspname as table_schema, cls.relname as table_name, con.conname as constraint_name, src.attname as column_name, refns.nspname as referenced_schema, refcls.relname as referenced_table, refatt.attname as referenced_column, case con.confupdtype when 'a' then 'NO ACTION' when 'r' then 'RESTRICT' when 'c' then 'CASCADE' when 'n' then 'SET NULL' when 'd' then 'SET DEFAULT' end as update_rule, case con.confdeltype when 'a' then 'NO ACTION' when 'r' then 'RESTRICT' when 'c' then 'CASCADE' when 'n' then 'SET NULL' when 'd' then 'SET DEFAULT' end as delete_rule, case con.confmatchtype when 'f' then 'FULL' when 'p' then 'PARTIAL' when 's' then 'SIMPLE' end as match_option, con.condeferrable as deferrable, con.condeferred as initially_deferred, key.ord as column_position from pg_constraint con join pg_class cls on cls.oid=con.conrelid join pg_namespace ns on ns.oid=cls.relnamespace join pg_class refcls on refcls.oid=con.confrelid join pg_namespace refns on refns.oid=refcls.relnamespace cross join lateral unnest(con.conkey,con.confkey) with ordinality key(attnum,refattnum,ord) join pg_attribute src on src.attrelid=cls.oid and src.attnum=key.attnum join pg_attribute refatt on refatt.attrelid=refcls.oid and refatt.attnum=key.refattnum where ns.nspname='public' and con.contype='f' order by cls.relname, con.conname, key.ord;
